import numpy as np

def z_func(x):
    return (np.sqrt(x**2 + 2) - x) / 2

def h(x):
    z = z_func(x)
    return 2 * (2*x**2 + 1)**2 * (1 - x*z) / (x**2 + 2*x*z)

def h_prime(x):
    eps = 1e-7
    return (h(x + eps) - h(x - eps)) / (2 * eps)

print(f"h_prime(0.5): {h_prime(0.5)}")
